import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class IsNotPrime {
    /**
     * * Write a Java function to identify non-prime numbers.
     *
     * > isNotPrime(2)
     * false
     * > isNotPrime(10)
     * true
     * > isNotPrime(35)
     * true
     */
    public static Boolean isNotPrime(int n) {
        if (n <= 1) {
            return true;
        }
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                return true;
            }
        }
        return false;
    }
}
